<script setup lang="ts">
import {ref,computed,onMounted,nextTick} from 'vue';
import {invoke} from '@tauri-apps/api/core';
import {money} from './model';
import Icon from './Icon.vue';
const props=defineProps<{action:(name:string,payload?:unknown)=>Promise<any>;reload:()=>Promise<void>;preview:boolean}>();
const state=ref<any>(null),repository=ref(''),busy=ref(false),error=ref(''),message=ref('');
const choices=ref<Record<string,string>>({}),confirmUpload=ref(false),recoveryExport=ref(false),recoveryImport=ref<any>(null);
const planElement=ref<HTMLElement|null>(null);
const native='__TAURI_INTERNALS__' in window;
const conflicts=computed<any[]>(()=>state.value?.plan?.conflicts||[]);
const unresolved=computed(()=>conflicts.value.filter(c=>!choices.value[c.id]).length);
const plan=computed(()=>state.value?.plan);
const rulesReady=computed(()=>state.value?.syncRules===2);
const replacement=computed(()=>!!plan.value&&['download','reset'].includes(plan.value.mode));
const needsConfirmation=computed(()=>replacement.value||(plan.value?.needsUpload&&plan.value?.firstUploadConfirmation&&!props.preview));
const operationNames:Record<string,string>={merge:'合并改动',download:'以远端替换本机',reset:'以本机重置远端'};
function changeText(delta:any){if(!delta)return '无';const rows=[['addedOrders','新增项目'],['updatedOrders','修改项目'],['trashedOrders','移入回收站'],['restoredOrders','恢复项目'],['removedOrders','移除项目'],['addedMoney','新增流水'],['changedMoney','修改或作废流水'],['removedMoney','移除流水']].filter(([key])=>delta[key]).map(([key,label])=>`${label} ${delta[key]}`);return rows.length?rows.join(' · '):'没有业务记录变化';}
function conflictLabel(field:string){if(!field.startsWith('task:'))return fields[field]||field;const key=field.split(':')[2];return '任务 · '+(({completion:'状态与实际时间',title:'名称',notes:'进度备注',dueDate:'截止日期',plannedStart:'计划开始',followUpDate:'跟进日期',waitingReason:'等待原因',reminderDays:'提前提醒',parentId:'所属阶段',dependsOn:'前置任务'} as Record<string,string>)[key||'']||'内容');}
function runDetails(item:any){try{return JSON.parse(item.details)}catch{return {}}}
function sideLabel(conflict:any,side:'local'|'remote'){const value=conflict[side];if(conflict.field==='record'&&conflict.collection==='orders')return value?.deletedAt?'保留删除，收支仍保留在记录中':'恢复 / 保留项目及该端修改';return side==='local'?'保留本机':'保留远端';}

async function refresh(){const value=await props.action('sync-status');state.value=value;repository.value=value.repository||value.defaultRepository||'';if(value.syncRules!==2)throw Error('同步规则更新待生效：请在设置的“本机后台管理”中退出后台，再关闭并重新打开工作台，程序会安装已准备的更新。原仓库配置已保留，尚未执行同步或替换。');}
async function run(task:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await task()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function configure(){await run(async()=>{state.value=await props.action('sync-configure',{repository:repository.value});message.value='仓库设置已保存，还未上传数据。';choices.value={};})}
async function finish(){state.value=await props.action('sync-commit',{choices:choices.value,confirmFirstUpload:confirmUpload.value,confirmReplacement:confirmUpload.value});await props.reload();const summary=state.value.summary;message.value=summary?`${operationNames[summary.mode]}已完成。上传：${changeText(summary.upload)}；本机更新：${changeText(summary.download)}。`:'本机与远端已确认一致。';choices.value={};confirmUpload.value=false;}
async function synchronize(mode='merge'){await run(async()=>{choices.value={};confirmUpload.value=false;state.value=await props.action('sync-prepare',{mode});message.value=state.value.plan.resetDetected?'远端已重置，或本机没有共同版本。已暂停合并，旧副本未上传。':state.value.plan.initialDownload?'本机为空，本次将获取远端完整账本，不会清空远端。':mode==='merge'?'已检查双方改动，请查看摘要后确认。':'已准备整本替换，请核对方向、数量及金额。';await nextTick();planElement.value?.scrollIntoView({block:'start',behavior:'smooth'});})}
async function cancel(){await run(async()=>{state.value=await props.action('sync-cancel');choices.value={};message.value='本次同步已取消，本地内容保留。';})}
async function downloadRecovery(){await run(async()=>{const key=await props.action('sync-export-recovery');const content=JSON.stringify(key,null,2);const name=`接单工作台-恢复密钥-${key.workspaceId.slice(0,8)}.deskkey`;if(native){const path=await invoke<string|null>('save_export',{name,content});if(!path)return;}else{const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}recoveryExport.value=false;message.value='恢复密钥已导出，请保存在私密位置。';})}
async function readRecovery(event:Event){const target=event.target as HTMLInputElement;const file=target.files?.[0];if(!file)return;try{if(file.size>20000)throw Error('所选文件过大，不是有效的恢复密钥');const content=await file.text();const value=JSON.parse(content);if(value.format!=='personal-order-desk.sync-recovery')throw Error('不是兼容的账本恢复密钥');recoveryImport.value={content,repository:value.repository,workspaceId:value.workspaceId,keyId:value.keyId};}catch(e){error.value=String(e)}finally{target.value=''}}
async function importRecovery(){await run(async()=>{state.value=await props.action('sync-import-recovery',{recovery:recoveryImport.value.content});repository.value=state.value.repository;await props.reload();recoveryImport.value=null;message.value='已导入恢复密钥。点击“检查同步”，获取远端账本。';})}
const fields:Record<string,string>={number:'订单编号',title:'项目名称',quoteCents:'订单金额',progress:'当前进度',nextStep:'下一步',notes:'备注',projectPath:'工程路径',trackingNumber:'快递单号',carrier:'快递公司',shippedDate:'寄出日期',deliveredDate:'收货日期',deletedAt:'删除状态',parentId:'关联原单',completion:'工作状态与完成日期',deadline:'类型与截止日期',record:'整条记录',physicalReminderDays:'实物提前提醒天数',digitalReminderDays:'其他提前提醒天数',receiptMethod:'默认收款方式',costMethod:'默认支出方式'};
function display(value:any,field:string):string{if(value===null||value===undefined)return '未记录';if(field==='quoteCents')return money(value);if(typeof value==='object'){const copy={...value};delete copy.revision;delete copy.id;return Object.entries(copy).map(([k,v])=>`${fields[k]||({tasks:'任务流程',title:'任务名称',parentId:'父任务',plannedStart:'计划开始',followUpDate:'跟进日期',reminderDays:'提前提醒天数',waitingReason:'等待原因',dependsOn:'前置任务',createdAt:'创建时间',startedAt:'实际开始',completedAt:'实际完成',status:'状态',completedDate:'完成日期',kind:'交付类型',acceptedDate:'接单日期',dueDate:'截止日期',amountCents:'金额',method:'收支方式',date:'日期',note:'备注',orderId:'项目标识',voidedAt:'作废时间',voidReason:'作废原因'} as Record<string,string>)[k]||k}：${k.endsWith('Cents')?money(String(v)):display(v,k)}`).join('\n')}return ({done:'已完成',doing:'进行中',todo:'未开始',waiting:'等待中',cancelled:'已取消',physical:'实物制作',simulation:'仿真',schematic:'原理图 / PCB',code:'代码 / 报告',receipt:'收款',cost:'支出',refund:'退款','cost-refund':'支出退回'} as Record<string,string>)[String(value)]||String(value)}
onMounted(()=>run(refresh));
</script>

<template>
 <section class="card sync-panel">
  <div class="section-heading"><div class="panel-title"><span class="panel-icon"><Icon name="settings"/></span><div><h2>远端同步</h2><p>本地先保存，完整副本离线保存，日常合并改动；整本替换单独确认。</p></div></div><span class="badge" :class="state?.configured?'blue':'muted'">{{busy?'正在读取…':!state?'状态未读取':!rulesReady?'待应用更新':state.configured?'已配置':'尚未配置'}}</span></div>
  <div class="settings-content">
   <div class="sync-status-strip"><div><span class="local-dot"/><strong>本地已保存</strong><small>{{state?.localChanges?`${state.changedOrders} 个项目、${state.changedMoney} 笔收支有待同步修改`:'远端新版本需点击同步后检查'}}</small></div><div><strong>上次远端确认</strong><small>{{state?.lastSyncedAt?new Date(state.lastSyncedAt).toLocaleString('zh-CN'):'尚未同步'}}</small></div><div v-if="state?.lastHead"><strong>确认版本</strong><small class="order-number">{{state.lastHead.slice(0,10)}}</small></div></div>
   <form class="sync-repository-form" @submit.prevent="configure"><label>私有同步仓库<div class="input-with-action"><input v-model="repository" required placeholder="例如 用户名/接单数据" :disabled="busy||preview"/><button :disabled="busy||state?.syncRules!==2" type="submit">保存设置</button></div><small>{{preview?'演示模式只连接专用测试仓库，不上传正式订单。':'只支持已授权的私有仓库；代码仓库与数据仓库分别保存。'}}</small></label></form>
   <div class="sync-main-actions"><button class="primary" :disabled="busy||!rulesReady||!state?.configured" @click="synchronize()"><Icon name="arrow"/>{{busy?'正在检查…':'检查同步'}}</button><button :disabled="busy" @click="run(refresh)">刷新状态</button><span class="muted">每次同步前先备份本机；远端更新保留加密保护副本。</span></div>
   <details v-if="rulesReady&&state?.configured" class="sync-advanced"><summary>高级操作 · 整本替换</summary><p>只作用于当前工作台。先备份，再显示预览；确认之前不会替换。新设备连接已有工作台请使用恢复密钥。</p><div class="row-actions"><button :disabled="busy" @click="synchronize('download')">从远端替换本机</button><button class="danger" :disabled="busy" @click="synchronize('reset')">以本机重置远端</button></div><small>重置后，其他设备的旧副本会暂停合并；旧版客户端需要升级。</small></details>
   <p v-if="message" class="sync-success" role="status">{{message}}</p><p v-if="error" class="error-banner" role="alert">{{error}}</p>
   <div v-if="plan&&rulesReady" ref="planElement" class="sync-plan" tabindex="-1">
    <div class="section-heading"><div><h3>{{operationNames[plan.mode]||'同步'}} · 内容预览</h3><p>仓库：{{state.repository}}</p></div><button class="text-button" :disabled="busy" @click="cancel">取消本次同步</button></div>
    <div class="sync-summary-grid"><div><small>本机</small><strong>{{plan.local.orders}} 个项目 / {{plan.local.money}} 笔收支 / {{plan.local.tasks||0}} 项任务</strong></div><div><small>远端</small><strong>{{plan.remote.orders}} 个项目 / {{plan.remote.money}} 笔收支 / {{plan.remote.tasks||0}} 项任务</strong></div><div><small>{{plan.resetDetected?'远端新账本':'操作完成后'}}</small><strong>{{plan.merged.orders}} 个项目 / {{plan.merged.money}} 笔收支 / {{plan.merged.tasks||0}} 项任务</strong></div></div>
    <div v-if="plan.resetDetected" class="sync-reset-warning" role="alert"><strong>已阻止旧副本回流</strong><p>远端账本已整本重置，或本机缺少共同版本。当前项目不会自动叠加到远端。</p><button :disabled="busy" @click="synchronize('download')">备份本机后，预览接受远端账本</button><small>若旧副本有需要保留的内容，可先取消并导出；暂不支持自动挑选迁入。</small></div>
    <template v-else><div class="sync-change-grid"><div><small>{{plan.mode==='reset'?'远端将被替换':plan.mode==='download'?'远端保持不变':'准备上传'}}</small><p>{{plan.mode==='download'?'本次不会上传本机改动':changeText(plan.upload)}}</p></div><div><small>本机将更新</small><p>{{changeText(plan.download)}}</p></div></div><div class="sync-money-preview"><span>已收款 <strong class="green">{{money(plan.merged.receivedCents||'0')}}</strong></span><span>实际支出 <strong>{{money(plan.merged.costCents||'0')}}</strong></span><span>实际利润 <strong :class="BigInt(plan.merged.profitCents||'0')<0n?'red':'green'">{{money(plan.merged.profitCents||'0')}}</strong></span><span>待收款 <strong class="red">{{money(plan.merged.remainingCents||'0')}}</strong></span></div><small v-if="conflicts.length" class="muted">未解决冲突前的金额为预估，最终按你的选择重新计算。</small><p v-if="plan.schemaUpgrade" class="sync-compatibility">首次同步将升级同步格式并建立代次标识，业务内容按合并结果保留；旧版客户端会停止同步，需要升级。</p></template>
    <p class="sync-backup-path">本机保护备份：{{plan.backupPath}}</p>
    <details v-if="plan.duplicateWarnings?.length" class="sync-duplicate-warning"><summary>发现 {{plan.duplicateWarnings.length}} 组疑似重复流水，请核对</summary><p>双方分别新增了同项目、同类型、同金额及同日期的流水。同步会保留两笔，不会擅自去重；若确为重复，可取消同步并先作废重复记录。</p><p v-for="(item,index) in plan.duplicateWarnings" :key="index">{{item.number}} · {{display(item.kind,'kind')}} {{money(item.amountCents)}} · {{item.date||'日期未知'}}</p></details>
    <div v-if="conflicts.length" class="sync-conflicts"><div class="sync-conflict-heading"><h3>{{conflicts.length}} 项冲突，尚有 {{unresolved}} 项未选择</h3><span>未选择前不会发布</span></div>
     <article v-for="conflict in conflicts" :key="conflict.id" class="sync-conflict"><h4>{{conflictLabel(conflict.field)}}<small>{{conflict.collection==='money'?'收支流水':conflict.collection==='preferences'?'偏好设置':'项目'}} · {{conflict.recordId.slice(0,8)}}</small></h4><p>{{conflict.reason}}</p><div class="sync-comparison"><label :class="{chosen:choices[conflict.id]==='local'}"><span><input v-model="choices[conflict.id]" type="radio" :name="conflict.id" value="local"/>{{sideLabel(conflict,'local')}}</span><pre>{{display(conflict.local,conflict.field)}}</pre></label><label :class="{chosen:choices[conflict.id]==='remote'}"><span><input v-model="choices[conflict.id]" type="radio" :name="conflict.id" value="remote"/>{{sideLabel(conflict,'remote')}}</span><pre>{{display(conflict.remote,conflict.field)}}</pre></label></div><details><summary>查看上次确认值</summary><pre>{{display(conflict.baseline,conflict.field)}}</pre></details></article>
    </div>
    <div v-if="!plan.resetDetected" class="sync-confirm-area"><label v-if="needsConfirmation" class="check-label first-upload-confirm"><input v-model="confirmUpload" type="checkbox"/>{{plan.mode==='reset'?'确认以本机整本重置远端，其他设备的旧副本将暂停合并':plan.mode==='download'?'确认备份后以远端整本替换本机，本机未上传改动不带入':'确认将这份账本加密上传到 '+state.repository}}</label><div class="sync-plan-footer"><button class="primary" :disabled="busy||unresolved>0||(needsConfirmation&&!confirmUpload)" @click="run(finish)">{{busy?'处理中…':plan.mode==='reset'?'确认重置远端':plan.mode==='download'?'确认替换本机':'确认合并并同步'}}</button><small>{{unresolved>0?`请先处理 ${unresolved} 项冲突`:needsConfirmation&&!confirmUpload?'请先勾选整本操作或首次上传确认。':'本机或远端若又有修改，会停止本次操作并要求重新检查。'}}</small></div></div>
   </div>
   <details v-if="state?.configured" class="sync-recovery"><summary>恢复密钥与新设备连接</summary><p>其他电脑连接同一本账本需要恢复密钥。丢失密钥后，仅凭 GitHub 登录无法解密远端数据。</p><div class="row-actions"><button :disabled="busy" @click="recoveryExport=true">导出恢复密钥</button><label class="file-button">导入恢复密钥<input type="file" accept=".deskkey,.json,application/json" :disabled="busy" @change="readRecovery"/></label></div><small>连接另一账本时，请先使用空的本地工作空间，避免混入已有项目。</small><small v-if="state.keyId" class="key-fingerprint">密钥标识 {{state.keyId.slice(0,16)}}</small></details>
   <div v-else class="sync-recovery"><label class="file-button">已有远端账本？导入恢复密钥<input type="file" accept=".deskkey,.json,application/json" @change="readRecovery"/></label></div>
   <details v-if="state?.runs?.length" class="sync-history"><summary>最近同步记录</summary><div v-for="(item,index) in state.runs" :key="index" class="history-row"><span>{{operationNames[runDetails(item).mode]||'已确认远端版本'}}<small v-if="runDetails(item).summary">上传：{{changeText(runDetails(item).summary.upload)}}<br/>本机更新：{{changeText(runDetails(item).summary.download)}}</small></span><small>{{new Date(item.at).toLocaleString('zh-CN')}}</small></div></details>
  </div>
 </section>
 <div v-if="recoveryExport" class="modal-layer upper"><section class="dialog compact" role="dialog" aria-modal="true" aria-label="导出恢复密钥"><div class="dialog-body"><h2>保存账本恢复密钥</h2><p>这份文件可以解密远端账本，请保存到私密位置，不要上传到公开仓库或发给他人。</p><div v-if="error" class="error-banner">{{error}}</div></div><footer class="dialog-footer"><button :disabled="busy" @click="recoveryExport=false">取消</button><button class="primary" :disabled="busy" @click="downloadRecovery">选择保存位置</button></footer></section></div>
 <div v-if="recoveryImport" class="modal-layer upper"><section class="dialog compact" role="dialog" aria-modal="true" aria-label="导入恢复密钥"><div class="dialog-body"><h2>连接恢复密钥对应的账本？</h2><p>仓库：{{recoveryImport.repository}}</p><p>账本：{{recoveryImport.workspaceId}}</p><p>导入前会先保护备份。已有不同账本的项目时会停止导入。</p><div v-if="error" class="error-banner">{{error}}</div></div><footer class="dialog-footer"><button :disabled="busy" @click="recoveryImport=null">取消</button><button class="primary" :disabled="busy" @click="importRecovery">导入并连接</button></footer></section></div>
</template>
